CREATE TABLE users (id VARCHAR(36) PRIMARY KEY, email VARCHAR(254) NOT NULL UNIQUE, password VARCHAR(100) NOT NULL, name VARCHAR(80) NOT NULL, role VARCHAR(20) NOT NULL CHECK(role IN ('CUSTOMER','BARISTA','ADMIN')), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ingredients (id VARCHAR(36) PRIMARY KEY, category VARCHAR(30) NOT NULL, name VARCHAR(80) NOT NULL, price INTEGER NOT NULL CHECK(price>=0), calories INTEGER NOT NULL CHECK(calories>=0), stock INTEGER NOT NULL CHECK(stock>=0), reserved INTEGER NOT NULL DEFAULT 0 CHECK(reserved>=0), threshold INTEGER NOT NULL DEFAULT 10, available BOOLEAN NOT NULL DEFAULT TRUE, notes VARCHAR(500) NOT NULL DEFAULT '', CHECK(stock>=reserved));
CREATE TABLE recipes (id VARCHAR(36) PRIMARY KEY, owner_id VARCHAR(36) NOT NULL REFERENCES users(id), name VARCHAR(80) NOT NULL, config TEXT NOT NULL, dna TEXT NOT NULL, share_token VARCHAR(64) UNIQUE, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE cafe_tables (id VARCHAR(36) PRIMARY KEY, label VARCHAR(40) NOT NULL UNIQUE, token VARCHAR(64) NOT NULL UNIQUE, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE barista_profiles (user_id VARCHAR(36) PRIMARY KEY REFERENCES users(id), specialty VARCHAR(120) NOT NULL, experience INTEGER NOT NULL DEFAULT 0, image_url VARCHAR(500));
CREATE TABLE orders (id VARCHAR(36) PRIMARY KEY, owner_id VARCHAR(36) NOT NULL REFERENCES users(id), recipe_id VARCHAR(36) NOT NULL REFERENCES recipes(id), snapshot TEXT NOT NULL, price INTEGER NOT NULL CHECK(price>=0), table_id VARCHAR(36) REFERENCES cafe_tables(id), barista_id VARCHAR(36) REFERENCES users(id), status VARCHAR(20) NOT NULL CHECK(status IN ('Created','Confirmed','Queued','Preparing','Crafting','Ready','Delivered','Completed','Cancelled')), stage INTEGER NOT NULL DEFAULT -1 CHECK(stage BETWEEN -1 AND 6), priority INTEGER NOT NULL DEFAULT 0, idempotency_key VARCHAR(36) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(owner_id,idempotency_key));
CREATE TABLE order_items (order_id VARCHAR(36) NOT NULL REFERENCES orders(id), ingredient_id VARCHAR(36) NOT NULL REFERENCES ingredients(id), quantity INTEGER NOT NULL CHECK(quantity>0), PRIMARY KEY(order_id,ingredient_id));
CREATE INDEX orders_owner ON orders(owner_id,created_at);
CREATE INDEX orders_queue ON orders(status,created_at);
CREATE TABLE records (id VARCHAR(36) PRIMARY KEY, kind VARCHAR(30) NOT NULL, body TEXT NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
